private void ReportHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);

}

private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
            totaliMeTVSH += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
            totaliPaTVSH += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
            zbritje = Convert.ToDouble(GetCurrentColumnValue("ZBRITJE"));
            tvshtotal = Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL"));
}

private void xrTableCell43_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
            furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
            e.Result = Math.Round(furnizimeTeTatueshme, 2);
            e.Handled = true;
}

private void xrTableCell43_SummaryReset(object sender, System.EventArgs e) {
            furnizimeTeTatueshme = 0;
}

private void xrTableCell43_SummaryRowChanged(object sender, System.EventArgs e) {
            furnizimeTeTatueshme = totalVleftaPaTvshPerArtMeTvsh * (1 - (Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) / Convert.ToDouble(GetCurrentColumnValue("TOTALI"))));
}

